import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BAQ5ZYJQ.js";const m=JSON.parse('{"title":"Tutorials","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/index.md","filePath":"tutorials/index.md","lastUpdated":1794863915000}'),o={name:"tutorials/index.md"};function s(d,e,i,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h1><p>Four walkthroughs, from reading a declaration to running on a cluster, a Windows VM, and several nodes at once.</p><table tabindex="0"><thead><tr><th></th><th>what it shows</th><th>needs</th></tr></thead><tbody><tr><td><a href="./environments">1 · Four environments</a></td><td>environments as stacks of layers, tags, building them, running in several at once, <code>--batch</code></td><td>reading, mostly</td></tr><tr><td><a href="./two-machines">2 · Numbers over two machines</a></td><td>one measurement taken here and on a server over ssh, recorded, compared a month later</td><td>an ssh host</td></tr><tr><td><a href="./cluster-and-vm">3 · A cluster, a Windows VM, and what is running</a></td><td>a training on Slurm with results brought back, an allocation kept warm, a Windows build from a Mac, <code>errand status</code>, <code>attach</code>, stopping everything</td><td>read it; reproducing needs a cluster and a Linux host with KVM</td></tr><tr><td><a href="./parallel">4 · A parallel computation</a></td><td>an MPI program with halo exchanges and an allreduce, <code>--ranks</code>, entries on several ranks, two nodes of a Slurm cluster in an Apptainer image</td><td>micromamba for the local part; a cluster for the rest</td></tr></tbody></table><p>The first one ships with errand, in <a href="https://github.com/hleclerc/errand/tree/main/examples/01-environments" target="_blank" rel="noreferrer"><code>examples/01-environments</code></a>. It names micromamba environments, Apptainer images, ssh hosts and a Slurm partition that do not exist on your machine: read it, adapt it, and <code>errand envs</code> tells you which of them are built here.</p><p><strong>Which first?</strong></p><ul><li>you want to see how a place is declared → <a href="./environments">1 · Four environments</a></li><li>you have a server and want comparable numbers → <a href="./two-machines">2 · Numbers over two machines</a></li><li>you have a cluster account, or need Windows → <a href="./cluster-and-vm">3 · A cluster, a Windows VM, and what is running</a></li><li>your code is MPI, or should be → <a href="./parallel">4 · A parallel computation</a></li></ul><h2 id="moved-to-the-guide" tabindex="-1">Moved to the guide <a class="header-anchor" href="#moved-to-the-guide" aria-label="Permalink to &quot;Moved to the guide&quot;">​</a></h2><ul><li>Running an existing pytest, Catch2 or cargo suite test by test: <a href="/errand/guide/runners/adopting">Adopting a suite</a>.</li><li>errand&#39;s own entries (<code>test</code>, <code>bench</code>, <code>track</code>, <code>Param</code>): <a href="/errand/guide/declaring-work">Writing entries</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">In a hurry</p><p>Read the <a href="/errand/guide/start">Quickstart</a>, then <a href="/errand/guide/environments">Environments</a> and <a href="/errand/guide/output">Results and records</a>. Everything else builds on those three.</p></div>',9)])])}const p=t(o,[["render",s]]);export{m as __pageData,p as default};
